<body>
<main class="wrap">
  <h1>Havi költségkövető</h1>
  <p class="lead">Add meg a havi bevételed és a kiadásaid kategóriáit — a kézzel rajzolt diagram megmutatja, mire költöttél.</p>

  <section class="card" aria-labelledby="inc-h">
    <h2 id="inc-h">Havi bevétel</h2>
    <label for="income">Bevétel (Ft)</label>
    <input id="income" type="number" min="0" step="1000" inputmode="numeric" placeholder="pl. 450000">
  </section>

  <section class="card" aria-labelledby="add-h">
    <h2 id="add-h">Új kiadás</h2>
    <div class="row">
      <div class="f">
        <label for="cat">Kategória</label>
        <input id="cat" list="catlist" placeholder="pl. Lakás, Étkezés">
        <datalist id="catlist">
          <option value="Lakás"></option><option value="Étkezés"></option>
          <option value="Közlekedés"></option><option value="Számlák"></option>
          <option value="Szórakozás"></option><option value="Egészség"></option>
          <option value="Vásárlás"></option><option value="Egyéb"></option>
        </datalist>
      </div>
      <div class="f">
        <label for="amt">Összeg (Ft)</label>
        <input id="amt" type="number" min="0" step="100" inputmode="numeric" placeholder="pl. 60000">
      </div>
      <button id="addBtn" class="primary" type="button">Hozzáad</button>
    </div>
  </section>

  <section class="card">
    <div class="stats">
      <div class="stat"><div class="k">Bevétel</div><div class="v" id="sInc">—</div></div>
      <div class="stat"><div class="k">Kiadás</div><div class="v" id="sExp">—</div></div>
      <div class="stat"><div class="k">Megmarad</div><div class="v" id="sRem">—</div></div>
    </div>
  </section>

  <section class="card" aria-labelledby="list-h">
    <h2 id="list-h">Kiadásaim</h2>
    <ul class="list" id="list"></ul>
    <p class="empty" id="empty">Még nincs kiadás. Add hozzá az elsőt fent — kategóriát és összeget.</p>
  </section>

  <section class="card" aria-labelledby="chart-h">
    <h2 id="chart-h">Költések kategóriák szerint</h2>
    <svg id="chart" class="chart" role="img" aria-label="Kiadások kategóriánként"></svg>
    <p class="hint" id="chartHint">A diagram a kategóriánkénti összesített kiadásokat mutatja.</p>
  </section>

  <p class="sr" id="status" aria-live="polite"></p>
</main>

<script>
(function(){
  var KEY = 'budget-tracker-v1';
  var nf = new Intl.NumberFormat('hu-HU');
  var state = { income: 0, expenses: [] };

  var incomeEl = document.getElementById('income');
  var catEl = document.getElementById('cat');
  var amtEl = document.getElementById('amt');
  var listEl = document.getElementById('list');
  var emptyEl = document.getElementById('empty');
  var chartEl = document.getElementById('chart');
  var chartHint = document.getElementById('chartHint');
  var statusEl = document.getElementById('status');

  function announce(msg){ statusEl.textContent = msg; }

  function load(){
    if (window.alfy && window.alfy.storage) {
      window.alfy.storage.get(KEY).then(function(v){
        if (v && typeof v === 'object') {
          state.income = Number(v.income) || 0;
          state.expenses = Array.isArray(v.expenses) ? v.expenses : [];
        }
        incomeEl.value = state.income || '';
        render();
      }).catch(function(){ render(); });
    } else { render(); }
  }

  function save(){
    if (window.alfy && window.alfy.storage) {
      try { window.alfy.storage.set(KEY, state); } catch(e){}
    }
  }

  function fmt(n){ return nf.format(Math.round(n)) + ' Ft'; }

  function totalExpenses(){
    return state.expenses.reduce(function(s,e){ return s + (Number(e.amount)||0); }, 0);
  }

  function grouped(){
    var m = {};
    state.expenses.forEach(function(e){
      var k = e.category || 'Egyéb';
      m[k] = (m[k] || 0) + (Number(e.amount)||0);
    });
    return Object.keys(m).map(function(k){ return {category:k, amount:m[k]}; })
      .sort(function(a,b){ return b.amount - a.amount; });
  }

  function renderStats(){
    var exp = totalExpenses();
    var rem = state.income - exp;
    document.getElementById('sInc').textContent = fmt(state.income);
    document.getElementById('sExp').textContent = fmt(exp);
    var remEl = document.getElementById('sRem');
    remEl.textContent = fmt(rem);
    remEl.className = 'v' + (rem < 0 ? ' neg' : '');
  }

  function renderList(){
    listEl.innerHTML = '';
    emptyEl.style.display = state.expenses.length ? 'none' : 'block';
    state.expenses.forEach(function(e, i){
      var li = document.createElement('li');
      var nm = document.createElement('span'); nm.className = 'nm'; nm.textContent = e.category;
      var am = document.createElement('span'); am.className = 'am'; am.textContent = fmt(e.amount);
      var del = document.createElement('button'); del.type = 'button'; del.className = 'icon';
      del.textContent = '×'; del.setAttribute('aria-label', 'Törlés: ' + e.category);
      del.addEventListener('click', function(){
        state.expenses.splice(i, 1); save(); render();
        announce('Törölve: ' + e.category);
      });
      li.appendChild(nm); li.appendChild(am); li.appendChild(del);
      listEl.appendChild(li);
    });
  }

  function seed(n, x, y, s){
    var t = Math.sin(n * 127.1 + 311.7) * 43758.5453;
    t = t - Math.floor(t);
    return [x + (t - 0.5) * s, y + (Math.sin(n * 269.5 + 183.3) * 43758.5453 % 1 - 0.5) * s];
  }

  function wobblyRect(x, y, w, h, s){
    var pts = [], n = 0, i;
    var corners = [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
    for (i = 0; i < 4; i++) {
      var a = corners[i], b = corners[(i + 1) % 4];
      var steps = Math.max(2, Math.round(Math.hypot(b[0]-a[0], b[1]-a[1]) / 26));
      for (var j = 0; j < steps; j++) {
        var t = j / steps;
        pts.push(seed(n++, a[0] + (b[0]-a[0])*t, a[1] + (b[1]-a[1])*t, s));
      }
    }
    var d = 'M' + pts[0][0].toFixed(1) + ' ' + pts[0][1].toFixed(1);
    for (i = 1; i < pts.length; i++) d += ' L' + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1);
    return d + ' Z';
  }

  function wobblyLine(x1, y1, x2, y2, s){
    var steps = Math.max(2, Math.round(Math.hypot(x2-x1, y2-y1) / 26));
    var d = 'M' + x1.toFixed(1) + ' ' + y1.toFixed(1);
    for (var i = 1; i <= steps; i++) {
      var t = i / steps;
      var p = seed(Math.random()*1000 + i, x1 + (x2-x1)*t, y1 + (y2-y1)*t, s);
      d += ' L' + p[0].toFixed(1) + ' ' + p[1].toFixed(1);
    }
    return d;
  }

  function renderChart(){
    var data = grouped();
    var W = 640, padL = 16, padR = 16, padT = 30, padB = 74;
    var plotW = W - padL - padR;
    var n = Math.max(1, data.length);
    var rowH = 58;
    var H = padT + padB + n * rowH;
    chartEl.setAttribute('viewBox', '0 0 ' + W + ' ' + H);

    var max = 0;
    data.forEach(function(d){ if (d.amount > max) max = d.amount; });
    if (max <= 0) max = 1;

    var svg = '';
    var baseX = padL;
    var baseY = padT + n * rowH;
    svg += '<path class="axis" d="' + wobblyLine(baseX, padT - 6, baseX, baseY + 2, 1.6) + '" fill="none"/>';
    svg += '<path class="axis" d="' + wobblyLine(baseX, baseY, W - padR, baseY, 1.6) + '" fill="none"/>';

    var barMax = plotW - 150;
    for (var i = 0; i < data.length; i++) {
      var d = data[i];
      var cy = padT + i * rowH + rowH / 2;
      var barH = 26;
      var bw = Math.max(4, (d.amount / max) * barMax);
      svg += '<path class="bar" d="' + wobblyRect(baseX, cy - barH/2, bw, barH, 2.2) + '"/>';
      var lbl = document.createElementNS('http://www.w3.org/2000/svg','text');
      var label = d.category.length > 16 ? d.category.slice(0,15) + '…' : d.category;
      svg += '<text class="lbl" x="' + (baseX + 2) + '" y="' + (cy - barH/2 - 5) + '">' + esc(label) + '</text>';
      svg += '<text class="val" x="' + (baseX + bw + 8) + '" y="' + (cy + 4) + '">' + esc(fmt(d.amount)) + '</text>';
    }
    chartEl.innerHTML = svg;

    chartHint.textContent = data.length
      ? 'A sávok hossza a kategóriánkénti összesített kiadást mutatja. Legnagyobb: ' + data[0].category + '.'
      : 'Adj hozzá kiadásokat, hogy megjelenjen a diagram.';
  }

  function esc(s){ return String(s).replace(/[&<>]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;'})[c]; }); }

  function render(){ renderStats(); renderList(); renderChart(); }

  function addExpense(){
    var cat = catEl.value.trim();
    var amt = parseFloat(amtEl.value);
    if (!cat) { announce('Add meg a kategóriát.'); catEl.focus(); return; }
    if (!(amt > 0)) { announce('Add meg a pozitív összeget.'); amtEl.focus(); return; }
    state.expenses.push({ category: cat, amount: amt });
    save(); render();
    catEl.value = ''; amtEl.value = ''; catEl.focus();
    announce('Hozzáadva: ' + cat + ' ' + fmt(amt));
  }

  document.getElementById('addBtn').addEventListener('click', addExpense);
  amtEl.addEventListener('keydown', function(e){ if (e.key === 'Enter') addExpense(); });
  incomeEl.addEventListener('input', function(){
    state.income = parseFloat(incomeEl.value) || 0; save(); renderStats();
  });

  load();
})();
</script>
</body>
</html>
